async function s(t,o={}){const e=await fetch(`${t}`,{headers:{"Content-Type":"application/json",...o.headers},...o});if(e.status!==204){if(!e.ok){const n=await e.json().catch(()=>({}));throw new Error(n.detail||`HTTP ${e.status}`)}return e.json()}}const i={get:t=>s(t),post:(t,o)=>s(t,{method:"POST",body:o!==void 0?JSON.stringify(o):void 0}),put:(t,o)=>s(t,{method:"PUT",body:JSON.stringify(o)}),del:t=>s(t,{method:"DELETE"})};export{i as a};
